const source = $input.item.json || {};
const msg = source.message || source.body?.message || {};
const directChatId = String(source.chatId || msg.chat?.id || '').trim();
const deliveryMode = String(source.deliveryMode || source.payload?.deliveryMode || '').trim().toLowerCase();
const scheduledFallbackChatId = String($env.TELEGRAM_ADMIN_CHAT_ID || '').trim();

let chatId = '';
let isAuto = false;

if (directChatId) {
  chatId = directChatId;
} else if (deliveryMode === 'return') {
  chatId = '';
} else {
  chatId = scheduledFallbackChatId;
  isAuto = Boolean(chatId);
}

return [{ json: { ...source, chatId, isAuto } }];

const source = $('Chuẩn bị ChatID').item.json || {};
const item = $input.item.json || {};
const owner = String($env.OWNER_DISPLAY_NAME || 'User').trim();

const updatedAt = String(item.updatedAt || item.updated_at || item.date || '').trim();
const buy = String(item.buy || item.mua_vao || item.buyPrice || '').trim();
const sell = String(item.sell || item.ban_ra || item.sellPrice || '').trim();

const formatMoney = (value = '') => {
  const digits = String(value).replace(/[^\d]/g, '');
  if (!digits) return value;
  return `${Number(digits).toLocaleString('vi-VN')} đ/lượng`;
};

const parts = [`Mia vừa lấy giá vàng SJC 9999 mới nhất cho ${owner}.`];
if (updatedAt) parts.push(`Dữ liệu cập nhật lúc ${updatedAt}.`);
if (buy || sell) parts.push(`Hiện mua vào ${formatMoney(buy || 'chưa rõ')}, bán ra ${formatMoney(sell || 'chưa rõ')}.`);

return [{ json: { chatId: source.chatId || '', text: parts.join(' ').trim() } }];

const source = $input.item.json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2 ($1)')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const rawText = String(
  source.text ||
  source.responseText ||
  source.output ||
  source.response ||
  ''
).trim();

const plainText = String(source.plainText || htmlToPlainText(rawText)).trim();

return [{
  json: {
    ...source,
    text: plainText || rawText
  }
}];
